const buf = new ArrayBuffer(8)
const bytes: Uint8Array = new Uint8Array(buf)
const ints: Int32Array = new Int32Array(buf)
bytes[0] = 1
console.log(ints[0])           // 1 — same 4 bytes as an i32

const bigs = new BigInt64Array(2)
